import {createWorld} from './world.js';
import {topics,findTopics,makeOutline,explorationRoute,readStored,entryRoutes,concerns,concernsFor,introSteps,INTRO_KEY} from './content.js';
import {coveredInset} from './motion.js';
import {bindSheet} from './sheets.js';
const $=s=>document.querySelector(s), list=$('#topic-list'), modal=$('#modal');
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let selected=null,category='全部',world,showConnections=true,previousFocus=null,entry=null,selectedConcern=null,detailOpener=null;
let stored={};try{stored=readStored(localStorage.getItem('writing-island-course'));}catch{}
let consultQuestions=Array.isArray(stored.questions)?stored.questions.filter(q=>typeof q==='string'&&q.trim()).slice(0,30):[];
let saved=new Set(Array.isArray(stored.saved)?stored.saved.filter(id=>topics.some(t=>t.id===id)):[]);
let answers=stored.answers&&typeof stored.answers==='object'&&!Array.isArray(stored.answers)?stored.answers:{};
let role=['學生','家長','其他'].includes(stored.role)?stored.role:'學生',note=typeof stored.note==='string'?stored.note:'';
function persist(){try{localStorage.setItem('writing-island-course',JSON.stringify({saved:[...saved],answers,role,note,questions:consultQuestions}));}catch{toast('瀏覽器無法儲存；本次操作仍可繼續，請先複製提綱。');}}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),3500);}
function renderList(){const visible=findTopics($('#search').value,category);list.innerHTML=visible.length?visible.map(t=>`<button class="topic-row ${t.id===selected?'active':''}" data-id="${t.id}" aria-pressed="${t.id===selected}"><span class="num">${t.n}</span><span><strong>${t.title}</strong><small>${t.tag} · ${t.steps.length} 個了解重點${saved.has(t.id)?' · 已加入清單':''}</small></span><span class="arrow">↗</span></button>`).join(''):'<p class="empty">沒有找到符合的主題。試試「收費」、「成果」或清除搜尋。</p>';$('#result-count').textContent=`${visible.length} 座主題島`;
world?.filter(visible.map(t=>t.id));}
list.addEventListener('click',e=>{const row=e.target.closest('[data-id]');if(row)selectTopic(row.dataset.id);});
function updateMap(){world?.select(selected);world?.connections(showConnections);}
function selectTopic(id,{focus=true,concern=null}={}){
 const t=topics.find(t=>t.id===id);if(!t)return;const moveCamera=id!==selected||$('#detail').hidden;if(focus&&!$('#detail').contains(document.activeElement))detailOpener=document.activeElement;selected=id;selectedConcern=concerns.find(c=>c.id===concern)||null;
 const related=[...new Set([...(selectedConcern?.related||[]),...t.links])];
 $('#detail-content').innerHTML=`<p class="eyebrow">ISLAND ${t.n} / ${t.title}</p><h2 id="detail-title">${selectedConcern?selectedConcern.question:t.title}</h2><div class="answer-first"><span class="draft-label">待老師補充</span><p class="lead">${selectedConcern?selectedConcern.answer:t.intro}</p></div><section class="card-section"><h3>01 · 具體做法，先確認這些</h3><ol>${t.steps.map(s=>`<li>${s}</li>`).join('')}</ol></section><details class="card-section evidence-section"><summary>02 · 目前資訊與證據 <span>待補充</span></summary><p>${t.body}</p><dl class="topic-facts">${t.facts.map(([label,value])=>`<div><dt>${label}</dt><dd>${value}</dd></div>`).join('')}</dl></details><details class="card-section question-notes" ${answers[id]?'open':''}><summary>03 · 補充你的情況 <span>選填</span></summary><div class="exercise"><label for="exercise-answer">${t.task}</label><textarea id="exercise-answer" maxlength="2000" placeholder="寫下你的顧慮、期待，或還想了解的事…">${escape(typeof answers[id]==='string'?answers[id]:'')}</textarea><small class="helper">只儲存在這個瀏覽器，不會傳送。</small><p class="question-example">${t.example}</p></div></details><section class="card-section"><h3>也可以一起了解</h3><div class="related">${related.map(id=>`<button data-related="${id}">${topics.find(t=>t.id===id).title} ↗</button>`).join('')}</div></section><div class="detail-actions"><button class="ask-topic" id="ask-topic">就這件事問老師 ↗</button><button class="save-topic" id="save-topic" aria-pressed="${saved.has(id)}">${saved.has(id)?'✓ 已收藏這個主題':'＋ 先收藏，晚點再聊'}</button><small>先整理諮詢提綱，不會直接送出訊息。</small></div>`;
 $('#detail').hidden=false;document.body.classList.add('detail-open');if(moveCamera&&matchMedia('(max-width:720px)').matches)$('#map').scrollIntoView({block:'start'});if(moveCamera)world?.focus(id,coveredInset($('#map').getBoundingClientRect(),$('#detail').getBoundingClientRect()));$('#map-message').textContent=`正在探索 ${t.title} · ${t.tag}`;
 $('#exercise-answer').oninput=e=>{answers[id]=e.target.value;persist();};
 $('#save-topic').onclick=()=>{saved.has(id)?saved.delete(id):saved.add(id);persist();updateCount();selectTopic(id,{focus:false,concern:selectedConcern?.id});$('#save-topic').focus();toast(saved.has(id)?'已加入討論清單':'已從討論清單移除');};
 $('#ask-topic').onclick=()=>{saved.add(id);const question=selectedConcern?.question||t.question;if(!consultQuestions.includes(question))consultQuestions.push(question);persist();updateCount();$('#save-topic').setAttribute('aria-pressed','true');$('#save-topic').textContent='✓ 已收藏這個主題';discussion();};
 for(const b of document.querySelectorAll('[data-related]'))b.onclick=()=>selectTopic(b.dataset.related);
 updateMap();renderList();if(focus){$('#detail').scrollTop=0;$('#close-detail').focus();}
}
function renderConcerns(){const items=concernsFor(entry);$('#concerns-list').innerHTML=items.map(c=>`<button data-concern="${c.id}"><span>${c.question}</span><span aria-hidden="true">↗</span></button>`).join('');$('#entry-note').textContent=entry?entryRoutes[entry].intro:'選一個問題，看看相關做法與待確認資訊。';world?.emphasize(entry?entryRoutes[entry].topics:[]);}
$('#concerns-list').onclick=e=>{const b=e.target.closest('[data-concern]');if(!b)return;const c=concerns.find(c=>c.id===b.dataset.concern);selectTopic(c.topic,{concern:c.id});};
for(const button of document.querySelectorAll('[data-entry]'))button.onclick=()=>{entry=button.dataset.entry;if(entryRoutes[entry].role){role=entryRoutes[entry].role;persist();}for(const b of document.querySelectorAll('[data-entry]'))b.setAttribute('aria-pressed',b===button);renderConcerns();if(entry==='teacher')selectTopic('teacher');else{if(!$('#detail').hidden)closeDetail();if(matchMedia('(max-width:720px)').matches)document.querySelector('.index').scrollIntoView({block:'start'});}};
function closeDetail(){const id=selected;$('#detail').hidden=true;document.body.classList.remove('detail-open');world?.refit();selected=null;updateMap();renderList();$('#map-message').textContent='點一座島，開始你的寫作旅程';const row=document.querySelector(`.topic-row[data-id="${id}"]`);const target=[detailOpener,row,$('#concerns-list button'),$('#topic-directory summary')].find(el=>el?.isConnected&&el.getClientRects().length);target?.focus();}
$('#close-detail').onclick=closeDetail;
$('#detail').addEventListener('keydown',e=>{if(e.key==='Escape'){e.preventDefault();closeDetail();}});
$('#search').oninput=renderList;for(const b of document.querySelectorAll('[data-category]'))b.onclick=()=>{category=b.dataset.category;for(const el of document.querySelectorAll('[data-category]')){el.classList.toggle('active',el===b);el.setAttribute('aria-pressed',el===b);}renderList();};
function updateCount(){$('#saved-count').textContent=saved.size;renderList();}
function showModal(html){if(!modal.open)previousFocus=document.activeElement;$('#modal-content').innerHTML=html;if(!modal.open)modal.showModal();$('#close-modal').focus();}
$('#close-modal').onclick=()=>modal.close();modal.addEventListener('close',()=>{if(document.activeElement===document.body||modal.contains(document.activeElement))previousFocus?.focus();});
function discussion(){showModal(`<p class="eyebrow">LET'S TALK ABOUT WRITING</p><h2>讓我們從問題開始。</h2><p>不用先想好答案，帶著一個真實的困難就好。</p>${consultQuestions.length?`<div class="consult-context"><small>想帶進討論的問題</small>${consultQuestions.map((q,i)=>`<div class="consult-question"><p>${escape(q)}</p><button data-remove-question="${i}" aria-label="移除問題：${escape(q)}">×</button></div>`).join('')}</div>`:''}<div id="saved-pills">${[...saved].map(id=>`<span class="pill">${topics.find(t=>t.id===id).title}<button data-remove="${id}" aria-label="移除${topics.find(t=>t.id===id).title}">×</button></span>`).join('')||'<p class="helper">尚未收藏主題；也可以直接寫下你的問題。</p>'}</div><label for="role">我是</label><select id="role">${['學生','家長','其他'].map(x=>`<option ${role===x?'selected':''}>${x}</option>`).join('')}</select><label for="note">目前的情況，或想和老師討論的事</label><textarea id="note" rows="4" maxlength="3000" placeholder="例如：想了解費用包含哪些服務，以及孩子的情況是否適合…">${escape(note)}</textarea><p class="helper">內容只留在你的瀏覽器。這裡不會寄送訊息，也不收集聯絡資料。</p><div class="modal-actions"><button class="primary" id="outline-button">產生討論提綱 ↗</button><button id="back-explore">繼續探索</button></div>`);$('#role').onchange=e=>{role=e.target.value;persist();};$('#note').oninput=e=>{note=e.target.value;persist();};for(const b of document.querySelectorAll('[data-remove-question]'))b.onclick=()=>{consultQuestions.splice(Number(b.dataset.removeQuestion),1);persist();discussion();};for(const b of document.querySelectorAll('[data-remove]'))b.onclick=()=>{saved.delete(b.dataset.remove);persist();updateCount();discussion();};$('#outline-button').onclick=outline;$('#back-explore').onclick=()=>modal.close();}
function outline(){const text=makeOutline(role,[...saved],note,answers,consultQuestions);showModal(`<p class="eyebrow">YOUR CONVERSATION STARTER</p><h2>把下一步，帶進對話。</h2><pre class="outline">${escape(text)}</pre><p class="helper">複製後，透過你平常與老師聯絡的管道分享。聯絡方式尚待教師提供。</p><div class="modal-actions"><button class="primary" id="copy">複製討論提綱</button><button id="download">下載文字檔</button><button id="edit-outline">返回編輯</button></div>`);$('#copy').onclick=async()=>{try{await navigator.clipboard.writeText(text);toast('已複製討論提綱');}catch{toast('無法存取剪貼簿，請下載文字檔或手動選取提綱。');}};$('#download').onclick=()=>{const url=URL.createObjectURL(new Blob([text],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='作文討論提綱.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};$('#edit-outline').onclick=discussion;}
$('#discuss').onclick=discussion;
$('#about').onclick=()=>showModal(`<p class="eyebrow">ABOUT THIS ISLAND</p><h2>先認識教學，再開始對話。</h2><p>「萬能考場作文：理論與實作」希望讓對教學有興趣的學生與家長，透過探索與提問，更清楚了解課程，並與老師討論自己的學習需求。</p><p>地圖連起老師的經驗與理念、上課方式、學習收穫、學生案例、收費，以及家長與學生的顧慮。你可以從最關心的事開始。</p><p class="helper">這是可操作的教學展示提案。教師介紹、正式課綱、授課對象、費用與聯絡方式尚待提供；目前呈現介紹架構與提問範例，不代表已確認的教學經歷、價格、服務或成效。</p><div class="modal-actions"><button class="primary" id="about-start">從認識老師開始 ↗</button></div>`);
$('#about').addEventListener('click',()=>{$('#about-start').onclick=()=>{modal.close();selectTopic('teacher');};});
let tourIndex=0;const tour=topics.map(t=>t.id);
function guide(){selectTopic(tour[tourIndex],{focus:false});const t=topics.find(t=>t.id===tour[tourIndex]);showModal(`<p class="eyebrow">A WALK THROUGH THE ISLAND</p><p class="tour-step">${String(tourIndex+1).padStart(2,'0')} / 09</p><h2>${t.title}</h2><p>${t.intro}</p><p>${t.body}</p><div class="progress"><span style="width:${(tourIndex+1)/9*100}%"></span></div><div class="modal-actions">${tourIndex?'<button id="tour-prev">← 上一步</button>':''}<button class="primary" id="tour-next">${tourIndex===8?'開始自由探索':'下一座島 →'}</button><button id="tour-exit">離開導覽</button></div>`);$('#tour-prev')?.addEventListener('click',()=>{tourIndex--;guide();});$('#tour-next').onclick=()=>{if(tourIndex===8){modal.close();$('#close-detail').focus();}else{tourIndex++;guide();}};$('#tour-exit').onclick=()=>{modal.close();$('#close-detail').focus();};}
$('#guide').onclick=()=>{tourIndex=0;guide();};
let quizIndex=0,quizAnswers=[];const questions=[{q:'你現在以什麼身分了解課程？',options:['我是學生，想判斷是否適合自己','我是家長，想了解孩子的學習安排']},{q:'目前最想先了解哪一部分？',options:['老師的經驗與教學理念','上課方式、收穫與學生成果','收費、安排與報名前的顧慮']},{q:'你希望接下來怎麼了解？',options:['先認識老師與課程','先看真實案例與成果的資訊','帶著自己的問題與老師討論']}];
function quiz(){const q=questions[quizIndex];showModal(`<p class="eyebrow">FIND YOUR STARTING POINT</p><p class="tour-step">${quizIndex+1} / 3 · 找到你的探索路線</p><h2>${q.q}</h2><div class="quiz-options">${q.options.map((s,i)=>`<button data-answer="${i}">${s} <span aria-hidden="true">↗</span></button>`).join('')}</div>${quizIndex?'<div class="modal-actions"><button id="quiz-prev">← 上一題</button></div>':''}`);$('#quiz-prev')?.addEventListener('click',()=>{quizIndex--;quiz();});for(const b of document.querySelectorAll('[data-answer]'))b.onclick=()=>{quizAnswers[quizIndex]=Number(b.dataset.answer);if(quizIndex<2){quizIndex++;quiz();}else quizResult();};}
function quizResult(){role=quizAnswers[0]===1?'家長':'學生';persist();const ids=explorationRoute(quizAnswers);showModal(`<p class="eyebrow">YOUR EXPLORATION ROUTE</p><h2>從這三座島開始。</h2><p>這是依照你的選擇安排的探索路線，不會評定能力，也不會判定你是否適合報名。</p><div class="quiz-options">${ids.map((id,i)=>`<button data-route="${id}">${i+1}. ${topics.find(t=>t.id===id).title} ↗</button>`).join('')}</div><div class="modal-actions"><button id="quiz-restart">重新選擇</button></div>`);for(const b of document.querySelectorAll('[data-route]'))b.onclick=()=>{modal.close();selectTopic(b.dataset.route);};$('#quiz-restart').onclick=()=>{quizIndex=0;quiz();};}
$('#quiz').onclick=()=>{quizIndex=0;quizAnswers=[];quiz();};
$('#reset').onclick=()=>{world?.home();if(!$('#detail').hidden)closeDetail();};
$('#zoom-in').onclick=()=>world?.zoom(.85);$('#zoom-out').onclick=()=>world?.zoom(1.15);
$('#connection').onclick=()=>{showConnections=!showConnections;$('#connection').setAttribute('aria-pressed',showConnections);updateMap();};
$('#pause').onclick=()=>{const paused=document.body.classList.toggle('paused');$('#pause').setAttribute('aria-pressed',paused);$('#pause').innerHTML=paused?'▷ <span>播放</span>':'Ⅱ <span>暫停</span>';world?.pause(paused);};
$('#day').onclick=()=>{const night=document.body.classList.toggle('night');$('#day').setAttribute('aria-pressed',night);world?.night(night);};
$('#rotate').onclick=()=>{const rotate=$('#rotate').getAttribute('aria-pressed')!=='true';$('#rotate').setAttribute('aria-pressed',rotate);world?.mode(rotate);$('#map-message').textContent=rotate?'旋轉模式 · 拖曳改變視角':'平移模式 · 拖曳上下左右移動';};
try{world=createWorld($('#map'),topics,id=>selectTopic(id));if(matchMedia('(prefers-reduced-motion: reduce)').matches){world.pause(true);document.body.classList.add('paused');$('#pause').setAttribute('aria-pressed','true');}}catch(error){$('#map').innerHTML='<p class="webgl-message">這個瀏覽器無法開啟 3D 地圖。請使用主題清單繼續探索。</p>';console.error(error);}
let introStep=0;const touch=matchMedia('(hover: none) and (pointer: coarse)').matches;
function finishIntro(){try{localStorage.setItem(INTRO_KEY,'1');}catch{}}
function intro(){const s=introSteps[introStep],last=introStep===introSteps.length-1;showModal(`<p class="eyebrow">HELLO, WRITER / 0${introStep+1}</p><h2>${s.title}</h2><p>${touch&&s.touchBody?s.touchBody:s.body}</p><div class="progress"><span style="width:${(introStep+1)/introSteps.length*100}%"></span></div><div class="modal-actions intro-actions"><button id="intro-skip">${introStep?'← 上一步':'略過'}</button><button class="primary" id="intro-next">${last?'開始探索 →':'下一步 →'}</button></div>`);$('#intro-next').focus();$('#intro-skip').onclick=()=>{if(introStep){introStep--;intro();}else modal.close();};$('#intro-next').onclick=()=>{if(last)modal.close();else{introStep++;intro();}};}
modal.addEventListener('close',()=>{if($('#intro-next'))finishIntro();});
updateCount();
$('#topic-directory').open=matchMedia('(min-width:721px)').matches;
renderConcerns();
let seenIntro=false;try{seenIntro=localStorage.getItem(INTRO_KEY)==='1';}catch{}if(!seenIntro&&world)intro();
// Read-only camera state for manual QA of pan / rotate / zoom / fly (no effect on the page).
window.__islandView=()=>world?.view();

let refitTimer;
function refitView(){clearTimeout(refitTimer);if(world?.flying()){refitTimer=setTimeout(refitView,100);return;}world?.refit($('#detail').hidden?{}:coveredInset($('#map').getBoundingClientRect(),$('#detail').getBoundingClientRect()));}
bindSheet($('#detail'),$('#detail-handle'),$('#detail-size'),{onChange:()=>requestAnimationFrame(refitView),onClose:closeDetail});
bindSheet($('#index-panel'),$('#index-handle'),$('#index-size'),{onClose:()=>$('#index-panel').classList.remove('sheet-full')});
$('#detail').addEventListener('transitionend',e=>{if(e.propertyName==='height')refitView();});
new ResizeObserver(()=>requestAnimationFrame(refitView)).observe($('#map'));

// Expose the same read-only QA state to browser tools that isolate page globals.
setInterval(()=>{if(world)$('#map').dataset.cameraView=JSON.stringify(world.view());},150);
